create or replace function private.command_configure_sponsor_funding(p_organization_id uuid,p_player_id uuid,p_benefit_id uuid,p_funding_source_name text,p_monthly_total numeric,p_funding_mode text,p_sponsor_value numeric,p_starts_on date,p_ends_on date,p_notes text) returns jsonb language plpgsql security definer set search_path='pg_catalog','public','app','private' as $$ declare v_benefit uuid; v_actor uuid:=(select auth.uid()); v_mode text:=lower(trim(coalesce(p_funding_mode,''))); begin if not private.has_financial_config_access(p_organization_id) then raise exception 'Financial configuration requires Presidencia or Contabilidad'; end if; if p_monthly_total is null or p_monthly_total<0 then raise exception 'Monthly total must be zero or greater'; end if; if v_mode not in ('fixed_amount','percentage') then raise exception 'Funding mode must be fixed_amount or percentage'; end if; if p_sponsor_value is null or p_sponsor_value<0 then raise exception 'Sponsor value must be zero or greater'; end if; if v_mode='fixed_amount' and p_sponsor_value>p_monthly_total then raise exception 'Sponsor amount cannot exceed monthly total'; end if; if v_mode='percentage' and p_sponsor_value>100 then raise exception 'Sponsor percentage cannot exceed 100'; end if; if nullif(trim(coalesce(p_funding_source_name,'')),'') is null then raise exception 'Funding source required'; end if; if p_ends_on is not null and p_ends_on<coalesce(p_starts_on,current_date) then raise exception 'Benefit end cannot precede start'; end if; if not exists(select 1 from app.players p where p.id=p_player_id and p.organization_id=p_organization_id and p.archived_at is null) then raise exception 'Player not found'; end if; update app.billing_profiles set base_monthly_fee=p_monthly_total,updated_at=now() where organization_id=p_organization_id and player_id=p_player_id; if not found then raise exception 'Billing profile not found'; end if; if p_benefit_id is null then insert into app.player_benefits(organization_id,player_id,benefit_type,calculation_type,fixed_amount,percentage,override_amount,funding_source_name,starts_on,ends_on,active,priority,notes,legacy_label,funding_configured_at,funding_configured_by_user_id,created_at,updated_at) values(p_organization_id,p_player_id,'sponsor_funded',v_mode,case when v_mode='fixed_amount' then p_sponsor_value else null end,case when v_mode='percentage' then p_sponsor_value else null end,null,trim(p_funding_source_name),coalesce(p_starts_on,current_date),p_ends_on,true,100,nullif(trim(coalesce(p_notes,'')),''),'Configurable sponsor funding',now(),v_actor,now(),now()) returning id into v_benefit; else update app.player_benefits set calculation_type=v_mode,fixed_amount=case when v_mode='fixed_amount' then p_sponsor_value else null end,percentage=case when v_mode='percentage' then p_sponsor_value else null end,override_amount=null,funding_source_name=trim(p_funding_source_name),starts_on=coalesce(p_starts_on,current_date),ends_on=p_ends_on,active=true,notes=nullif(trim(coalesce(p_notes,'')),''),funding_configured_at=now(),funding_configured_by_user_id=v_actor,updated_at=now() where id=p_benefit_id and organization_id=p_organization_id and player_id=p_player_id and benefit_type='sponsor_funded' returning id into v_benefit; if v_benefit is null then raise exception 'Sponsor benefit not found'; end if; end if; insert into app.domain_events(organization_id,event_type,aggregate_type,aggregate_id,payload,actor_user_id) values(p_organization_id,'SponsorFundingConfigured','player_benefit',v_benefit,jsonb_build_object('playerId',p_player_id,'monthlyTotal',p_monthly_total,'fundingSource',trim(p_funding_source_name),'mode',v_mode,'sponsorValue',p_sponsor_value,'startsOn',coalesce(p_starts_on,current_date),'endsOn',p_ends_on),v_actor); return jsonb_build_object('benefitId',v_benefit,'playerId',p_player_id,'monthlyTotal',p_monthly_total,'fundingSource',trim(p_funding_source_name),'mode',v_mode,'sponsorValue',p_sponsor_value); end $$;
create or replace function private.query_sponsor_funding(p_organization_id uuid,p_player_id uuid default null) returns table(benefit_id uuid,player_id uuid,player_name text,monthly_total numeric,funding_source_name text,funding_mode text,sponsor_value numeric,starts_on date,ends_on date,active boolean,configured_at timestamptz) language plpgsql stable security definer set search_path='pg_catalog','app','private' as $$ begin if not private.has_module_access(p_organization_id,'billing',false) then raise exception 'Not authorized'; end if; return query select b.id,p.id,trim(concat_ws(' ',p.first_name,p.last_name)),bp.base_monthly_fee,b.funding_source_name,b.calculation_type,case when b.calculation_type='percentage' then b.percentage else b.fixed_amount end,b.starts_on,b.ends_on,b.active,b.funding_configured_at from app.player_benefits b join app.players p on p.id=b.player_id and p.organization_id=b.organization_id join app.billing_profiles bp on bp.player_id=p.id and bp.organization_id=p.organization_id where b.organization_id=p_organization_id and b.benefit_type='sponsor_funded' and (p_player_id is null or p.id=p_player_id) order by p.first_name,p.last_name,b.starts_on desc,b.created_at desc; end $$;
create or replace function app.generate_monthly_charges(p_organization_id uuid,p_period date) returns integer language plpgsql security definer set search_path='pg_catalog','app','public' as $$ declare v_period date:=date_trunc('month',p_period)::date; v_policy app.billing_policies%rowtype; v_count integer:=0; r record; v_benefit app.player_benefits%rowtype; v_total numeric; v_sponsor numeric; v_family numeric; v_start date; begin select * into v_policy from app.billing_policies where organization_id=p_organization_id; if not found then raise exception 'Billing policy not configured'; end if; if v_period<date_trunc('month',v_policy.effective_from)::date then return 0; end if; for r in select bp.*,p.id as pid from app.billing_profiles bp join app.players p on p.id=bp.player_id and p.organization_id=bp.organization_id where bp.organization_id=p_organization_id and bp.status='active' and p.status='active' and p.archived_at is null and bp.needs_review=false and bp.base_monthly_fee>0 and date_trunc('month',bp.billing_start)::date<=v_period loop v_total:=app.prorated_monthly_fee(r.base_monthly_fee,r.billing_start,v_period,v_policy.proration_method); v_sponsor:=0; v_benefit:=null; select b.* into v_benefit from app.player_benefits b where b.organization_id=p_organization_id and b.player_id=r.pid and b.benefit_type='sponsor_funded' and b.active=true and b.funding_configured_at is not null and b.calculation_type in ('fixed_amount','percentage') and b.starts_on<=(v_period+interval '1 month - 1 day')::date and (b.ends_on is null or b.ends_on>=v_period) order by b.priority desc,b.starts_on desc,b.created_at desc limit 1; if found then if v_benefit.calculation_type='percentage' then v_sponsor:=round(v_total*least(100,greatest(0,coalesce(v_benefit.percentage,0)))/100.0,2); else v_start:=greatest(r.billing_start,coalesce(v_benefit.starts_on,r.billing_start)); v_sponsor:=app.prorated_monthly_fee(coalesce(v_benefit.fixed_amount,0),v_start,v_period,v_policy.proration_method); end if; v_sponsor:=least(v_total,greatest(0,v_sponsor)); end if; v_family:=greatest(0,v_total-v_sponsor); if v_family>0 then insert into app.charges(organization_id,player_id,billing_profile_id,charge_type,billing_period,concept,amount,due_date,status,source,late_fee_eligible,idempotency_key,posted_at,payer_type,payer_name,player_benefit_id) values(p_organization_id,r.pid,r.id,'monthly_fee',v_period,'Mensualidad '||to_char(v_period,'YYYY-MM'),v_family,app.month_due_date(v_period,v_policy.due_day),'posted','billing_engine',case when date_trunc('month',r.billing_start)::date=v_period then v_policy.first_month_late_fee_enabled else true end,'monthly-family:'||r.pid::text||':'||to_char(v_period,'YYYY-MM'),now(),'guardian',null,case when v_benefit.id is null then null else v_benefit.id end) on conflict do nothing; if found then v_count:=v_count+1; end if; end if; if v_sponsor>0 then insert into app.charges(organization_id,player_id,billing_profile_id,charge_type,billing_period,concept,amount,due_date,status,source,late_fee_eligible,idempotency_key,posted_at,payer_type,payer_name,player_benefit_id) values(p_organization_id,r.pid,r.id,'monthly_fee_sponsor',v_period,'Mensualidad patrocinada · '||coalesce(v_benefit.funding_source_name,'Sponsor')||' · '||to_char(v_period,'YYYY-MM'),v_sponsor,app.month_due_date(v_period,v_policy.due_day),'posted','billing_engine',false,'monthly-sponsor:'||r.pid::text||':'||v_benefit.id::text||':'||to_char(v_period,'YYYY-MM'),now(),'sponsor',v_benefit.funding_source_name,v_benefit.id) on conflict do nothing; if found then v_count:=v_count+1; end if; end if; end loop; return v_count; end $$;
create or replace function app.generate_academy_charges(p_organization_id uuid,p_period date) returns integer language plpgsql security definer set search_path='pg_catalog','app','public' as $$ declare v_period date:=date_trunc('month',p_period)::date; v_policy app.billing_policies%rowtype; v_count integer:=0; r record; v_fee numeric; begin select * into v_policy from app.billing_policies where organization_id=p_organization_id; if not found then raise exception 'Billing policy not configured'; end if; if v_period<date_trunc('month',v_policy.effective_from)::date then return 0; end if; for r in select ae.id enrollment_id,ae.player_id,ae.starts_on,ae.ends_on,coalesce(ae.agreed_fee,a.monthly_fee,0) monthly_fee,a.name academy_name,bp.id billing_profile_id from app.academy_enrollments ae join app.academies a on a.id=ae.academy_id and a.organization_id=ae.organization_id left join app.billing_profiles bp on bp.player_id=ae.player_id and bp.organization_id=ae.organization_id join app.players p on p.id=ae.player_id and p.organization_id=ae.organization_id where ae.organization_id=p_organization_id and ae.status in ('active','cancelled') and p.archived_at is null and ae.starts_on<=(v_period+interval '1 month - 1 day')::date and (ae.ends_on is null or ae.ends_on>=v_period) and coalesce(ae.agreed_fee,a.monthly_fee,0)>0 loop v_fee:=app.prorated_monthly_fee(r.monthly_fee,r.starts_on,v_period,v_policy.proration_method); if v_fee<=0 then continue; end if; insert into app.charges(organization_id,player_id,billing_profile_id,charge_type,billing_period,concept,amount,due_date,status,source,late_fee_eligible,idempotency_key,posted_at,payer_type,academy_enrollment_id) values(p_organization_id,r.player_id,r.billing_profile_id,'academy_fee',v_period,'Academia '||r.academy_name||' · '||to_char(v_period,'YYYY-MM'),v_fee,app.month_due_date(v_period,v_policy.due_day),'posted','billing_engine',case when date_trunc('month',r.starts_on)::date=v_period then v_policy.first_month_late_fee_enabled else true end,'academy:'||r.enrollment_id::text||':'||to_char(v_period,'YYYY-MM'),now(),'guardian',r.enrollment_id) on conflict do nothing; if found then v_count:=v_count+1; end if; end loop; return v_count; end $$;
create or replace function app.assess_late_fees(p_organization_id uuid,p_as_of date) returns integer language plpgsql security definer set search_path='pg_catalog','app','public' as $$ declare v_policy app.billing_policies%rowtype; v_count integer:=0; begin select * into v_policy from app.billing_policies where organization_id=p_organization_id; insert into app.charges(organization_id,player_id,billing_profile_id,parent_charge_id,charge_type,billing_period,concept,amount,due_date,status,source,late_fee_eligible,idempotency_key,posted_at,payer_type,payer_name,academy_enrollment_id,player_benefit_id) select c.organization_id,c.player_id,c.billing_profile_id,c.id,'late_fee',c.billing_period,'Recargo · '||c.concept,v_policy.late_fee_amount,p_as_of,'posted','billing_engine',false,'late-fee:'||c.id::text,now(),c.payer_type,c.payer_name,c.academy_enrollment_id,c.player_benefit_id from app.charges c join app.charge_balances cb on cb.id=c.id where c.organization_id=p_organization_id and c.charge_type in ('monthly_fee','academy_fee') and c.status='posted' and c.late_fee_eligible=true and cb.balance_due>0 and c.billing_period>=date_trunc('month',v_policy.effective_from)::date and p_as_of>c.due_date on conflict do nothing; get diagnostics v_count=row_count; return v_count; end $$;
create or replace function private.command_run_billing(p_organization_id uuid,p_period date,p_as_of date) returns jsonb language plpgsql security definer set search_path='pg_catalog','public','app','private' as $$ declare v_club integer; v_academy integer; v_late integer; begin if not private.has_module_access(p_organization_id,'admin',true) then raise exception 'Not authorized'; end if; v_club:=app.generate_monthly_charges(p_organization_id,p_period); v_academy:=app.generate_academy_charges(p_organization_id,p_period); v_late:=app.assess_late_fees(p_organization_id,p_as_of); return jsonb_build_object('club_charges_created',v_club,'academy_charges_created',v_academy,'charges_created',v_club+v_academy,'late_fees_created',v_late); end $$;
create or replace function private.run_billing_automation() returns jsonb language plpgsql security definer set search_path='pg_catalog','public','app','private' as $$ declare r record; v_local_date date; v_local_hour integer; v_period date; v_club integer; v_academy integer; v_late integer; v_results jsonb:='[]'::jsonb; begin for r in select o.id,o.slug,o.timezone from public.organizations o join app.billing_policies bp on bp.organization_id=o.id where o.status='active' loop v_local_date:=(now() at time zone coalesce(nullif(r.timezone,''),'UTC'))::date; v_local_hour:=extract(hour from (now() at time zone coalesce(nullif(r.timezone,''),'UTC')))::integer; if v_local_hour<>3 then continue; end if; v_period:=date_trunc('month',v_local_date)::date; v_club:=0; v_academy:=0; if extract(day from v_local_date)=1 then v_club:=app.generate_monthly_charges(r.id,v_period); v_academy:=app.generate_academy_charges(r.id,v_period); end if; v_late:=app.assess_late_fees(r.id,v_local_date); v_results:=v_results||jsonb_build_array(jsonb_build_object('organization',r.slug,'local_date',v_local_date,'club_charges_created',v_club,'academy_charges_created',v_academy,'late_fees_created',v_late)); end loop; return v_results; end $$;
create or replace function private.command_post_payment(p_organization_id uuid,p_player_id uuid,p_amount numeric,p_payment_date date,p_method text,p_reference text,p_concept text,p_payer_type text,p_payer_name text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='pg_catalog','public','app','private' as $$ declare v_id uuid; v_actor uuid:=(select auth.uid()); v_payer_type text:=coalesce(nullif(trim(p_payer_type),''),'guardian'); begin if not private.has_module_access(p_organization_id,'billing',true) then raise exception 'Not authorized'; end if; if p_amount is null or p_amount<=0 then raise exception 'Amount must be greater than zero'; end if; if p_idempotency_key is null or length(trim(p_idempotency_key))<8 then raise exception 'Idempotency key required'; end if; if v_payer_type not in ('guardian','sponsor','player','organization','other') then raise exception 'Invalid payer type'; end if; if v_payer_type='sponsor' and nullif(trim(coalesce(p_payer_name,'')),'') is null then raise exception 'Sponsor name required'; end if; if not exists(select 1 from app.players where id=p_player_id and organization_id=p_organization_id) then raise exception 'Player not found'; end if; select id into v_id from app.payments where organization_id=p_organization_id and idempotency_key=trim(p_idempotency_key); if v_id is not null then return v_id; end if; insert into app.payments(organization_id,player_id,amount,payment_date,method,reference,concept,status,source,category,idempotency_key,payer_type,payer_name,payment_purpose,credit_status,created_at,updated_at) values(p_organization_id,p_player_id,p_amount,coalesce(p_payment_date,current_date),coalesce(nullif(trim(p_method),''),'other'),nullif(trim(p_reference),''),coalesce(nullif(trim(p_concept),''),'Mensualidad'),'posted','tanneros_v2','Mensualidad',trim(p_idempotency_key),v_payer_type,nullif(trim(p_payer_name),''),'billing','available',now(),now()) returning id into v_id; perform app.allocate_payment_oldest_first(v_id); insert into app.domain_events(organization_id,event_type,aggregate_type,aggregate_id,payload,actor_user_id,request_id) values(p_organization_id,'PaymentPosted','payment',v_id,jsonb_build_object('player_id',p_player_id,'amount',p_amount,'payment_date',coalesce(p_payment_date,current_date),'payerType',v_payer_type,'payerName',nullif(trim(p_payer_name),'')),v_actor,trim(p_idempotency_key)); return v_id; end $$;
create or replace function public.v2_configure_sponsor_funding(organization_id uuid,player_id uuid,benefit_id uuid,funding_source_name text,monthly_total numeric,funding_mode text,sponsor_value numeric,starts_on date,ends_on date,notes text) returns jsonb language sql security definer set search_path='pg_catalog','private' as $$ select private.command_configure_sponsor_funding(organization_id,player_id,benefit_id,funding_source_name,monthly_total,funding_mode,sponsor_value,starts_on,ends_on,notes) $$;
create or replace function public.v2_sponsor_funding(organization_id uuid,player_id uuid default null) returns table(benefit_id uuid,player_id uuid,player_name text,monthly_total numeric,funding_source_name text,funding_mode text,sponsor_value numeric,starts_on date,ends_on date,active boolean,configured_at timestamptz) language sql stable security definer set search_path='pg_catalog','private' as $$ select * from private.query_sponsor_funding(organization_id,player_id) $$;
revoke execute on function public.v2_configure_sponsor_funding(uuid,uuid,uuid,text,numeric,text,numeric,date,date,text) from public,anon; revoke execute on function public.v2_sponsor_funding(uuid,uuid) from public,anon; grant execute on function public.v2_configure_sponsor_funding(uuid,uuid,uuid,text,numeric,text,numeric,date,date,text) to authenticated; grant execute on function public.v2_sponsor_funding(uuid,uuid) to authenticated;;
